3	export function verifySignature(secret: string, body: string, header: string | null) {
4	  if (!header) return false;
5	  const expected = createHmac("sha256", secret).update(body).digest("hex");
6	  const provided = header.startsWith("sha256=") ? header.slice(7) : header;
7	  const a = Buffer.from(expected, "hex");
8	  const b = Buffer.from(provided, "hex");
9	  if (a.length !== b.length) return false;
10	  return timingSafeEqual(a, b);
11	}

